mapper.select:
select
    change_score
from credit_record
where user_id = #{userId}
  and business_type = #{businessType}
  and business_id = #{businessId}
  and change_type = 2
order by id desc
limit 1

select a.id, a.booking_id, b.booking_no, a.reason, a.appeal_status, a.deduct_score, a.audit_remark, a.create_time as appeal_time, a.audit_time from booking_breach_appeal a left join booking b on a.booking_id = b.id where a.user_id = #{userId} and a.is_deleted = 0
and a.appeal_status = #{appealStatus}
order by a.id desc

select a.id, a.booking_id, b.booking_no, a.user_id, u.username, u.real_name, a.reason, a.appeal_status, a.deduct_score, a.audit_remark, a.audit_user_id, a.create_time as appeal_time, a.audit_time from booking_breach_appeal a left join booking b on a.booking_id = b.id left join sys_user u on a.user_id = u.id where a.is_deleted = 0
and a.appeal_status = #{appealStatus}
order by a.id desc
